<?php
declare(strict_types=1); require_once __DIR__.'/core/database.php'; require_once __DIR__.'/event-lib.php'; require_once __DIR__.'/core/html-sanitizer.php';
$st=$pdo->prepare("SELECT n.*,e.title event_title,e.slug event_slug FROM event_news n JOIN events e ON e.id=n.event_id WHERE n.slug=? AND n.status='published' LIMIT 1");$st->execute([trim((string)($_GET['slug']??''))]);$news=$st->fetch();if(!$news){http_response_code(404);exit('خبر پیدا نشد.');}$pageTitle=$news['title'];require __DIR__.'/dashboard/components/header/component.php';
?><?php
$relatedStmt=$pdo->prepare("SELECT id,title,slug,published_at FROM event_news WHERE event_id=? AND status='published' AND id<>? ORDER BY published_at DESC,id DESC LIMIT 4");$relatedStmt->execute([(int)$news['event_id'],(int)$news['id']]);$related=$relatedStmt->fetchAll();
