</style><main class="event-news-page"><div class="event-news-layout"><article class="event-news-wrap"><a class="event-news-back" href="/event.php?slug=<?= rawurlencode($news['event_slug']) ?>">← بازگشت به صفحه همایش</a><div class="event-news-label">خبر اختصاصی · <?= event_h($news['event_title']) ?></div><h1><?= event_h($news['title']) ?></h1><div class="event-news-meta"><?= event_h($news['published_at'] ?: $news['created_at']) ?></div><?php if($news['image']): ?><div class="event-news-figure"><img src="<?= event_h($news['image']) ?>" alt=""></div><?php endif; ?><div class="event-news-body"><?= HtmlSanitizer::sanitize((string)$news['content']) ?></div></article><?php if($related): ?><aside class="event-news-related"><h2>دیگر اخبار همایش</h2><?php foreach($related as $item): ?><a href="/event-news.php?slug=<?= rawurlencode($item['slug']) ?>"><?= event_h($item['title']) ?><time><?= event_h($item['published_at'] ?: '') ?></time></a><?php endforeach; ?></aside><?php endif; ?></div></main><?php require __DIR__.'/dashboard/components/footer/component.php';
